import java.lang.ref.PhantomReference;
import java.lang.ref.Reference;
import java.lang.ref.ReferenceQueue;

public class ResourceCleaner {
    public static void main(String[] args) throws InterruptedException {
        ReferenceQueue<byte[]> queue = new ReferenceQueue<>();
        byte[] heavyResource = new byte[1024 * 1024 * 10]; // 10MB
        PhantomReference<byte[]> phantomRef = new PhantomReference<>(heavyResource, queue);

        // Drop strong reference
        heavyResource = null;

        // Force GC for demonstration purposes
        System.gc();

        // Poll the reference queue to detect reclamation
        Reference<? extends byte[]> ref = queue.remove(1000);
        if (ref == phantomRef) {
            System.out.println("Object memory reclaimed. Perform off-heap cleanup here.");
        }
    }
}
